html:
{#- Surat jalan ke customer ("DO asli"), dicetak dari Sales Invoice - bentuknya sama kayak Delivery
    Order di Delivery Note. Baris Barang Tambahan gak dicetak. DO No., tanggal, Vehicle No., dan
    Serial No-nya: lihat get_invoice_delivery_order di vic/print_utils.py. -#}
{%- set dlv = get_invoice_delivery_order(doc) -%}
{%- set print_date = dlv.date -%}
{#- tujuan kirim: alamat pengiriman kalau beda dari alamat customer, kalau gak ada pakai project -#}
{%- set delivered_to = doc.shipping_address if (doc.shipping_address_name and doc.shipping_address_name != doc.customer_address) else None -%}
{%- set project_name = frappe.db.get_value("Project", doc.project, "project_name") if doc.project else None -%}

<style>
	/* kotak Customer & Delivered To, judulnya nempel di garis atas */
	.vic-pf .parties { width: 100%; margin-top: 14px; }
	.vic-pf .parties .left { width: 62%; padding-right: 18px !important; }
	/* dibatesin ke .parties: blok alamat company di kop juga pakai class `box`, jangan ikut digaris */
	.vic-pf .parties .box {
		border: 1px solid #000;
		border-radius: 3px;
		padding: 7px 10px 8px;
		margin-bottom: 10px;
		position: relative;
	}
	.vic-pf .parties .box .cap {
		position: absolute;
		top: -7px;
		left: 9px;
		background: #fff;
		padding: 0 4px;
		font-size: 9px;
	}
	.vic-pf .parties .box .name { font-weight: 700; }
	.vic-pf .parties .box .addr { font-size: 10px; }
	.vic-pf .ship .lbl { width: 80px; }
	.vic-pf .ship .sep { width: 12px; }
	.vic-pf .items td { padding-bottom: 14px !important; }
	.vic-pf .serials { margin-top: 8px; font-weight: 400; }
	.vic-pf .serials div { word-break: break-all; }
	/* lima blok tanda tangan sama lebar, dikotakin; garisnya dipaksa !important (CSS print Frappe
	   ngenolin border sel), jabatan di atas dengan garis bawah, ruang tanda tangan di bawahnya */
	.vic-pf .sign { table-layout: fixed; }
	.vic-pf .sign td { width: 20%; border: 1px solid #000 !important; padding: 6px 6px 8px !important; }
	.vic-pf .sign td .role { border-bottom: 1px solid #000; padding-bottom: 4px; margin-bottom: 58px; font-weight: 700; }
</style>

<div class="vic-pf">
	{%- include "vic_addon/templates/print_formats/vic_letterhead.html" -%}

	<div class="title-wrap">
		<div class="title-block">
			<div class="doc-title">DELIVERY ORDER</div>
			<table class="meta">
				<tr>
					<td class="lbl">DO No.</td>
					<td class="sep">:</td>
					<td>{{ dlv.do_no }}</td>
				</tr>
				<tr>
					<td class="lbl">Date</td>
					<td class="sep">:</td>
					<td>{{ frappe.utils.formatdate(print_date, "MMMM d, yyyy") }}</td>
				</tr>
			</table>
		</div>
	</div>

	<table class="parties">
		<tr>
			<td class="left">
				<div class="box">
					<span class="cap">Customer</span>
					<div class="name">{{ doc.customer_name or doc.customer }}</div>
					{%- if doc.address_display %}<div class="addr">{{ doc.address_display }}</div>{% endif %}
				</div>

				<div class="box">
					<span class="cap">Delivered To</span>
					<div>{{ delivered_to or project_name or doc.customer_name or doc.customer }}</div>
				</div>
			</td>
			<td>
				<table class="ship">
					<tr>
						<td class="lbl">Vehicle No.</td>
						<td class="sep">:</td>
						<td>{{ dlv.vehicle_no }}</td>
					</tr>
					<tr>
						<td class="lbl">PO No.</td>
						<td class="sep">:</td>
						<td>{{ doc.po_no or "" }}</td>
					</tr>
				</table>
			</td>
		</tr>
	</table>

	<table class="items">
		<thead>
			<tr>
				<th style="width: 8%">Item</th>
				<th class="left" style="width: 52%">Description</th>
				<th style="width: 15%">Qty</th>
				<th style="width: 25%">Remarks</th>
			</tr>
		</thead>
		<tbody>
			{%- set ns = namespace(no = 0) %}
			{%- for group in group_items(dlv.rows) %}
				{%- set indent = group.indent %}
				{#- Pengerjaan paling atas, di bawahnya Pengiriman, terus item (lihat vic/item_header.py) -#}
				{%- if group.pengerjaan %}
					<tr class="group pengerjaan"><td></td><td class="text" colspan="3">{{ group.pengerjaan }}</td></tr>
				{%- endif %}
				{%- if group.header %}
					{#- judul kelompok mulai di kolom Description, kolom sebelumnya dikosongin -#}
					<tr class="group"><td></td><td class="text {{ group.header_indent }}" colspan="3">{{ group.header }}</td></tr>
				{%- endif %}
				{%- for item in group.rows %}
					{%- set ns.no = ns.no + 1 %}
					{%- set size = frappe.db.get_value("Item", item.item_code, "custom_size") %}
					{%- set serials = dlv.serials.get(item.name) %}
					{%- set qty = item.qty | float %}
					<tr>
						<td class="num">{{ ns.no }}</td>
						<td class="text {{ indent }}">
							<div class="desc">{{ get_item_description(item) }}</div>
							{%- if size %}<div>Size : {{ size }}</div>{% endif %}
							{%- if serials %}
								<div class="serials">
									Serial Number :
									{%- for serial_no in serials %}<div>- {{ serial_no }}</div>{% endfor %}
								</div>
							{%- endif %}
						</td>
						<td class="qty">{{ qty | int if qty == qty | round(0) else "%.2f" | format(qty) }} {{ item.uom }}</td>
						<td></td>
					</tr>
				{%- endfor %}
			{%- endfor %}
		</tbody>
	</table>

	{#- nama di kolom tanda tangan sengaja dikosongin, diisi tanda tangan basah -#}
	<table class="sign">
		<tr>
			<td>
				<div class="role">Issued By</div>
				<div>{{ frappe.db.get_value("User", doc.owner, "full_name") or "" }}</div>
			</td>
			{%- for role in ["Approved by", "Warehouse", "Delivered by", "Received by"] %}
				<td>
					<div class="role">{{ role }}</div>
					<div>&nbsp;</div>
				</td>
			{%- endfor %}
		</tr>
	</table>
	{%- include "vic_addon/templates/print_formats/vic_footer.html" -%}
</div>
